/*
 * Server side of the RPC procedures declared in awale_rpc.x.
 * main() and the network part are generated by rpcgen (awale_rpc_svc.c).
 *
 * Each procedure finds the user from its token, runs the command with the
 * same code as the socket version (commands.c, game.c, awale.c), and returns
 * what was queued in the user's mailbox.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>

#include "awale_rpc.h"
#include "user.h"
#include "game.h"
#include "commands.h"

/* rpcgen returns a pointer to a static result: we free the previous one at each call */
static char *last_text = NULL;

static char **return_text(char *text)
{
   free(last_text);
   last_text = text;
   return &last_text;
}

/* done once, at the first call */
static void init_server(void)
{
   static int done = 0;
   if(!done)
   {
      srand(time(NULL));
      mkdir(PROFILE_DIR, 0755);
      mkdir(SAVE_DIR, 0755);
      done = 1;
   }
}

/* RPC has no connection: a client that stopped polling is considered gone */
static void check_timeouts(void)
{
   time_t now = time(NULL);
   int i;
   for(i = 0; i < MAX_CLIENTS; i++)
   {
      if(users[i].in_use && now - users[i].last_seen > USER_TIMEOUT)
      {
         printf("%s timed out\n", users[i].name);
         command_disconnect(i);
      }
   }
}

/* finds the user of a token and remembers that this client is alive, -1 if unknown */
static int get_user(int token)
{
   int u;
   init_server();
   check_timeouts();
   u = user_find_token(token);
   if(u != -1)
   {
      users[u].last_seen = time(NULL);
   }
   return u;
}

login_reply *login_1_svc(char **name, struct svc_req *req)
{
   static login_reply reply;
   char line[NAME_LEN + 1];
   int u;
   (void)req;

   init_server();
   check_timeouts();
   free(reply.text);
   reply.text = NULL;
   reply.token = 0;

   u = user_add();
   if(u == -1)
   {
      reply.text = strdup("Server full, sorry.\n");
      return &reply;
   }

   strncpy(line, *name, NAME_LEN);
   line[NAME_LEN] = 0;
   if(command_login(u, line))
   {
      reply.token = users[u].token;
      printf("%s logged in\n", users[u].name);
   }
   reply.text = user_take_mailbox(u);
   if(reply.token == 0)
   {
      user_remove(u); /* name refused */
   }
   fflush(stdout);
   return &reply;
}

char **command_1_svc(command_args *args, struct svc_req *req)
{
   int u = get_user(args->token);
   (void)req;

   if(u == -1)
   {
      return return_text(strdup("Unknown session, please restart the client.\n"));
   }
   command_handle(u, args->line);
   /* the answer, and after a move the new board: "pushed" right away to the player */
   return return_text(user_take_mailbox(u));
}

char **poll_1_svc(int *token, struct svc_req *req)
{
   int u = get_user(*token);
   (void)req;

   if(u == -1)
   {
      return return_text(strdup("Unknown session, please restart the client.\n"));
   }
   return return_text(user_take_mailbox(u));
}

void *logout_1_svc(int *token, struct svc_req *req)
{
   static char dummy;
   int u = get_user(*token);
   (void)req;

   if(u != -1)
   {
      printf("%s logged out\n", users[u].name);
      fflush(stdout);
      command_disconnect(u);
   }
   return &dummy;
}
